fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Ensure inputs have the same length
    assert_eq!(a.len(), b.len(), "Input slices must have the same length");

    // Zip the two vectors together, compute bitwise OR for each pair,
    // and collect the results into a new vector.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x | y)
     .collect()
}

